// Committed font metric data (packages/engine/data/fonts/*.json, generated by
// `bun engine codegen`). The format mirrors a TFM file: shared dimension tables
// plus per-character indices, so it stays compact and decodes losslessly.

import type { FixWordFont } from "./font"

export const FONT_DATA_FORMAT = 1

export interface FontData {
  format: number
  name: string
  checksum: number
  designSize: number
  /** Dimension tables in fix_words; index 0 is always 0. */
  widths: number[]; heights: number[]; depths: number[]; italics: number[]
  /** [code, widthIdx, heightIdx, depthIdx, italicIdx, tag, remainder] */
  chars: [number, number, number, number, number, number, number][]
  ligKern: number[]
  kerns: number[]
  /** 1-based like TFM; params[0] is unused. */
  params: number[]
  /** extensible recipes, in fonts that have them */
  exten?: number[]
}

export function decodeFontData(d: FontData): FixWordFont {
  if (d.format !== FONT_DATA_FORMAT) throw new Error(`font data ${d.name}: format ${d.format}, expected ${FONT_DATA_FORMAT}`)
  const chars: FixWordFont["chars"] = new Map()
  for (const [c, w, h, dp, i, tag, remainder] of d.chars) {
    chars.set(c, { width: d.widths[w], height: d.heights[h], depth: d.depths[dp], italic: d.italics[i], tag, remainder })
  }
  return { name: d.name, checksum: d.checksum, designSize: d.designSize, chars, ligKern: d.ligKern, kerns: d.kerns, params: d.params, ...(d.exten ? { exten: d.exten } : {}) }
}

export function encodeFontData(f: FixWordFont): FontData {
  const table = () => { const vals = [0]; const idx = new Map<number, number>([[0, 0]]); return { vals, at: (v: number) => { let i = idx.get(v); if (i === undefined) { i = vals.length; vals.push(v); idx.set(v, i) } return i } } }
  const w = table(), h = table(), dp = table(), it = table()
  const chars: FontData["chars"] = [...f.chars.entries()].sort((a, b) => a[0] - b[0])
    .map(([c, m]) => [c, w.at(m.width), h.at(m.height), dp.at(m.depth), it.at(m.italic), m.tag, m.remainder])
  return { format: FONT_DATA_FORMAT, name: f.name, checksum: f.checksum, designSize: f.designSize, widths: w.vals, heights: h.vals, depths: dp.vals, italics: it.vals, chars, ligKern: f.ligKern, kerns: f.kerns, params: f.params, ...(f.exten ? { exten: f.exten } : {}) }
}
